(() => {
  const hdr = document.querySelector('.site-header'), hero = document.querySelector('.hero'), bar = document.querySelector('.specbar');
  const r = el => Math.round(el.getBoundingClientRect().height);
  const b = bar.getBoundingClientRect();
  return {vh: innerHeight, header: r(hdr), hero: r(hero), bar: r(bar),
          total: r(hdr)+r(hero)+r(bar), barBottom: Math.round(b.bottom),
          ok: Math.abs(b.bottom - innerHeight) <= 1};
})()
